select 'fn|'||p.oid::regprocedure::text||'|'||md5(pg_get_functiondef(p.oid)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','app')
union all select 'col|'||c.relnamespace::regnamespace||'.'||c.relname||'.'||a.attname||'|'||format_type(a.atttypid,a.atttypmod)||'|'||a.attnotnull||'|'||coalesce(pg_get_expr(d.adbin,d.adrelid),'') from pg_attribute a join pg_class c on c.oid=a.attrelid left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where c.relnamespace in ('public'::regnamespace,'app'::regnamespace) and c.relkind in ('r','p') and a.attnum>0 and not a.attisdropped
union all select 'con|'||c.relname||'|'||k.conname||'|'||pg_get_constraintdef(k.oid) from pg_constraint k join pg_class c on c.oid=k.conrelid where c.relnamespace in ('public'::regnamespace,'app'::regnamespace)
union all select 'idx|'||indexdef from pg_indexes where schemaname in ('public','app')
union all select 'trg|'||pg_get_triggerdef(t.oid) from pg_trigger t join pg_class c on c.oid=t.tgrelid where not t.tgisinternal and c.relnamespace in ('public'::regnamespace,'app'::regnamespace)
union all select 'pol|'||c.relname||'|'||p.polname||'|'||p.polcmd::text||'|'||coalesce(pg_get_expr(p.polqual,p.polrelid),'')||'|'||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),'') from pg_policy p join pg_class c on c.oid=p.polrelid where c.relnamespace in ('public'::regnamespace,'app'::regnamespace)
union all select 'view|'||c.relname||'|'||md5(pg_get_viewdef(c.oid,true))||'|'||coalesce(c.reloptions::text,'') from pg_class c where c.relkind='v' and c.relnamespace='public'::regnamespace
union all select 'tblgrant|'||c.relname||'|'||coalesce((select string_agg(coalesce(r.rolname,'PUBLIC')||':'||a.privilege_type, ',' order by r.rolname, a.privilege_type) from aclexplode(c.relacl) a left join pg_roles r on r.oid=a.grantee where a.grantee<>c.relowner),'') from pg_class c where c.relnamespace in ('public'::regnamespace,'app'::regnamespace) and c.relkind in ('r','v','p')
union all select 'fngrant|'||p.oid::regprocedure::text||'|'||coalesce((select string_agg(coalesce(r.rolname,'PUBLIC'), ',' order by r.rolname) from aclexplode(p.proacl) a left join pg_roles r on r.oid=a.grantee where a.grantee<>p.proowner),'<default>') from pg_proc p where p.pronamespace in ('public'::regnamespace,'app'::regnamespace)
union all select 'rls|'||c.relname||'|'||c.relrowsecurity||'|'||c.relforcerowsecurity from pg_class c where c.relnamespace in ('public'::regnamespace,'app'::regnamespace) and c.relkind='r'
union all select 'seq|'||sequencename||'|'||start_value||'|'||increment_by||'|'||max_value from pg_sequences where schemaname in ('public','app')
order by 1;
